bool OTableConnection::CheckHit( const Point& rMousePos ) const
    {
        // check if the point hit our line
        return std::any_of(m_vConnLine.begin(),
                             m_vConnLine.end(),
                             [&rMousePos]
                             ( const std::unique_ptr<OConnectionLine> & pLine )
                             { return pLine->CheckHit( rMousePos ); } );
    }
